import{_ as a,E as n,h as o,c as i,b as t,f as s,H as c,a4 as d}from"./chunks/framework.B_fYP6Of.js";const k=JSON.parse('{"title":"ADR 003 · Workflow ownership","description":"An architecture decision record on retrying document enrichment safely, committing current results once, and comparing Dagster with Temporal for workflow recovery.","frontmatter":{"title":"ADR 003 · Workflow ownership","description":"An architecture decision record on retrying document enrichment safely, committing current results once, and comparing Dagster with Temporal for workflow recovery.","teaser":"A worker finishes just after its source is replaced. Who can accept the result, retry the job, or show the reader the last valid version?"},"headers":[],"relativePath":"decisions/003-workflow-ownership.md","filePath":"decisions/003-workflow-ownership.md"}'),l={name:"decisions/003-workflow-ownership.md"};function h(p,e,u,m,f,w){const r=n("LabArticleHeader");return o(),i("div",null,[e[0]||(e[0]=t("h1",{id:"adr-003-·-workflow-ownership",tabindex:"-1"},[s("ADR 003 · Workflow ownership "),t("a",{class:"header-anchor",href:"#adr-003-·-workflow-ownership","aria-label":'Permalink to "ADR 003 · Workflow ownership"'},"​")],-1)),c(r),e[1]||(e[1]=d('<p><em>Architecture decision record · Single-owner rule adopted for the draft. Execution engine open.</em></p><p>This decision assigns responsibility for moving background work forward. Dagster and Temporal remain candidates. Both must be compared on the same recovery cases.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A corrected source can invalidate an entity match while leaving useful text search intact. Parsing, chunking, language processing, named-entity recognition, entity resolution, relationship extraction, indexing, and augmentation each depend on different inputs. Track those inputs so the system can recover an interrupted job without replacing valid work with stale output.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Model ingestion as a DAG over versioned artifacts. One durable orchestrator owns readiness, retries, attempts, timeouts, cancellation, and dependency progression. Evaluate Dagster and Temporal before selecting a runtime. NATS/JetStream carries relevant system events and durable work only where that does not duplicate orchestration ownership.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The workflow engine may use its own task queues and state database. SQLite retrieval storage does not automatically become workflow control storage. Jobs reference artifacts and fingerprints rather than transporting entire documents in broker messages.</p><p>Commit the output before announcing readiness. Combine idempotent writes, an input-version check, an outbox record, and reconciliation so the stored state can settle a dispute. A broker acknowledgment tells you about message delivery. It cannot prove that an external model executed a request exactly once.</p><h2 id="alternatives-and-tradeoffs" tabindex="-1">Alternatives and tradeoffs <a class="header-anchor" href="#alternatives-and-tradeoffs" aria-label="Permalink to &quot;Alternatives and tradeoffs&quot;">​</a></h2><p>Pure event choreography distributes dependency logic across consumers and makes joins, cancellation, and recovery harder to inspect. A custom scheduler would require implementing durable leases, fencing, retries, dependency joins, and upgrades. It needs a concrete justification before adoption.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Use the same interrupted publication for Dagster and Temporal. Give revision 1 to a worker and let it commit its output. Lose the acknowledgment, replace the source with revision 2, then restart the worker and redeliver the original task. Let revision 2 finish.</p><p>For each engine, keep the attempt history, artifact identities, publication record and the revision a new search returns. The old commit can stay in history. Redelivery must reuse or reject the completed attempt without making revision 1 current again. Only the eligible revision 2 should be searchable after its publication. Engine selection remains open until those traces exist.</p><p>Kill a worker before and after commit; redeliver a task; replace or delete a source mid-run; correct an entity merge; interrupt a model call; and verify that completed independent artifacts remain usable. Compare operational recovery and incremental reprocessing with representative document workloads. See <a href="/knowledge-lab/architecture/ingestion">ingestion</a>.</p>',15))])}const b=a(l,[["render",h]]);export{k as __pageData,b as default};
